/* AK-74M: the Block Bench model (data above). Parts keep the model's names, so the bolt carrier, trigger and magazine can move.
   Size: the model is scaled so its length is a real AK-74 (0.943 m). Colours are per part (no texture image is in the file). */
function buildAK74M(){
 const root=new T.Group();
 const nodes=AK74M.n.map(nd=>{const g=new T.Group();g.name=nd.n;
  if(nd.t)g.position.fromArray(nd.t);if(nd.r)g.quaternion.fromArray(nd.r);if(nd.s)g.scale.fromArray(nd.s);
  if(nd.m){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(nd.m,3));geo.setIndex(nd.ix);
   const flat=geo.toNonIndexed();flat.computeVertexNormals();g.add(new T.Mesh(flat,GM[nd.k]||GM.stl))}
  return g});
 AK74M.n.forEach((nd,i)=>{if(nd.p>=0)nodes[nd.p].add(nodes[i])});
 const byName=n=>nodes.find(x=>x.name===n);
 const b=nodes[AK74M.root];root.add(b);
 root.updateMatrixWorld(true);
 const len=new T.Box3().setFromObject(root);const S=0.943/(len.max.z-len.min.z);b.scale.setScalar(S);
 root.updateMatrixWorld(true);
 const box=o=>new T.Box3().setFromObject(o),cen=bx=>bx.getCenter(new T.Vector3());
 /* put the rear sight at x = 0, its top at the sight line (y = .092) and its centre at z = -.125, as the other guns */
 const rear=box(byName('RearSight')),rc=cen(rear),all=box(root);
 b.position.add(new T.Vector3(-rc.x,.092-rear.max.y,-.125-rc.z));
 root.updateMatrixWorld(true);
 const at=n=>cen(box(byName(n))),r2=box(byName('RearSight')),f2=box(byName('FrontsightMuzzel')),a2=box(root);
 const pg=at('pistolgrip'),fe=at('Forend'),mg=at('magazine');
 /* hands: the grip and the forend, with the elbows kept at the same offsets as the old AK */
 const rh=[pg.x,pg.y,pg.z],lh=[fe.x,fe.y,fe.z];
 const rE=[rh[0]+.07,rh[1]-.18,rh[2]+.45],lE=[lh[0]-.3,lh[1]-.245,lh[2]+.77];
 const h=hands(root,{rh,rE,lh,lE});
 const mag=byName('magazine');
 const m=finish(root,b,h.arms,h.lh,mag,{lhTo:[mg.x-fe.x,mg.y-fe.y,mg.z-fe.z],sight:[0,r2.max.y,cen(r2).z],front:[0,f2.max.y,cen(f2).z],muz:[0,f2.max.y,a2.min.z]});
 /* the bolt carrier and the trigger follow the file's own keyframes, played from each shot */
 const trig=byName('Trigger');
 const keep=[AK74M.n.findIndex(x=>x.n==='Boltcarrier'),AK74M.n.findIndex(x=>x.n==='Trigger')];
 const chans=AK74M.a.filter(c=>keep.includes(c.node)).map(c=>{
  const o=nodes[c.node],S3=c.path==='translation'?3:4;const t=c.times.slice(),v=c.values.slice();
  if(o===trig){const rest=v.slice(0,S3);t.push(t[t.length-1]+.06);v.push(...rest)}   /* the trigger springs back */
  return{o,path:c.path,t,v}});
 const q=new T.Quaternion(),q2=new T.Quaternion(),v3=new T.Vector3(),v4=new T.Vector3();
 function sample(c,tm){const n=c.t.length;let i=0;while(i<n-1&&c.t[i+1]<=tm)i++;const j=Math.min(i+1,n-1);
  const t0=c.t[i],t1=c.t[j],f=t1>t0?Math.min(1,Math.max(0,(tm-t0)/(t1-t0))):0;
  if(c.path==='translation'){v3.fromArray(c.v,i*3);v4.fromArray(c.v,j*3);c.o.position.copy(v3.lerp(v4,f))}
  else{q.fromArray(c.v,i*4);q2.fromArray(c.v,j*4);c.o.quaternion.copy(q.slerp(q2,f))}}
 m.cyc=1e9;m.onShot=()=>{m.cyc=0};
 /* reload: grab (gun tilts in, left hand to the magazine), magazine out (tilts, drops ~12.5 cm, falls away),
    magazine in (rises from below, tilts back, hand lets go), finish (gun levels and the bolt carrier racks back and forward) */
 const boltN=byName('Boltcarrier'),boltRest=boltN.position.z,magRest=mag.position.clone(),DROP=.125,SC=b.scale.x;
 const ss=x=>x*x*(3-2*x),c01=x=>Math.min(1,Math.max(0,x));
 m.resetPose=()=>{boltN.position.z=boltRest;mag.rotation.set(0,0,0);mag.position.copy(magRest)};
 m.reloadPose=(r,p,o)=>{let tilt=1,lhk=1,dropM=0,rx=0,vis=true,back=0;
  if(r===0){tilt=ss(p);lhk=ss(p)}
  else if(r===1){const a=ss(c01(p/.35)),f=ss(c01((p-.35)/.65));rx=.25*a;dropM=DROP*f;lhk=a;vis=f<.85}
  else if(r===2){const f=1-ss(p);dropM=DROP*f;rx=.25*f;vis=p>.1;lhk=1-ss(c01((p-.7)/.3))}
  else{tilt=1-ss(p);lhk=1-ss(p);back=Math.sin(Math.PI*p)*.6}
  mag.visible=vis;mag.rotation.x=rx;mag.position.set(magRest.x,magRest.y-dropM/SC,magRest.z);
  m.lh.position.set(m.lhTo[0]*lhk,(m.lhTo[1]-dropM)*lhk,m.lhTo[2]*lhk);
  boltN.position.z=boltRest+back;
  o[0]=-.03*tilt;o[1]=.09*tilt;o[2]=.07*tilt;o[3]=.38*tilt;o[4]=-.5*tilt};
 m.anim=dt=>{m.cyc+=dt;const tm=Math.min(m.cyc,1);for(const c of chans)sample(c,tm)};
 return m}
